                      </div>
                    </div>
                  )}
                </div>

                {/* Deliberation section */}
                {!resultsFinalized && (
                  <div className="card" style={{marginBottom:"1rem"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:".5rem",marginBottom:".75rem"}}>
