                      const awardDraft = awardDrafts[p.id] ?? savedAward;
                      const awardDirty = awardDraft !== savedAward;
                      return (
                        <div key={p.id} style={{borderTop:"1px solid var(--bd)",paddingTop:".85rem",marginTop:".85rem"}}>
