                            </div>
                            <div style={{textAlign:"right",flexShrink:0}}>
                              <div style={{fontFamily:"var(--ff-d)",fontSize:"1.5rem",color:"var(--navy)"}}>{p.avg ?? "—"}</div>
                              <div style={{fontSize:".65rem",color:"var(--dim)"}}>avg / {projectMax(p)}</div>
                            </div>
                          </div>
