                                        <div key={li} style={{marginLeft:"68px",fontSize:".78rem",color: line.startsWith("⚠") ? "var(--red)" : "var(--dim)",fontStyle: line.startsWith("⚠") ? "normal" : "italic",lineHeight:1.5,borderLeft:"2px solid var(--bd)",paddingLeft:".5rem"}}>
                                          {line}
                                        </div>
                                      ))}
                                    </div>
                                  );
                                })}
                              </div>
