                        <div className="sec-title" style={{marginBottom:0}}>{g.label}</div>
                        <div>
                          {st.state === "open" && chip("bb", "Not confirmed", "st-open")}
                          {st.state === "confirmed" && chip("bg", "✓ Confirmed", "st-confirmed")}
